// @FIGURE_CODE_BEGIN
var SERIF = "Georgia,'Times New Roman',serif";
var fhDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var FW = 1120, FH = 800;
fhDraw.viewbox(0, 0, FW, FH);

var GRAY = '#d3d3d3', INK = '#111', ORANGE = '#e07b00', TEAL = '#0b8f88', TEALFILL = '#a8e3dc';
var R = 21, ROFF = 8, RWRAP = 46, REXT = 32, RRAD = 14;
var ROWA = [72, 168, 255];
var ROWB = [95, 275, 445];

var N = {
  n23: { k: 23, x: 130, d: 0 },
  n7:  { k: 7,  x: 265, d: 0 },
  n3:  { k: 3,  x: 480, d: 0, kids: ['n18', 'n52', 'n38'], child: 'n52' },
  n17: { k: 17, x: 755, d: 0, kids: ['n30'], child: 'n30' },
  n24: { k: 24, x: 915, d: 0, kids: ['n26', 'n46'], child: 'n26' },
  n21: { k: 21, x: 1020, d: 0 },
  n18: { k: 18, x: 390, d: 1, mark: true, p: 'n3', kids: ['n39'], child: 'n39' },
  n52: { k: 52, x: 480, d: 1, p: 'n3' },
  n38: { k: 38, x: 570, d: 1, p: 'n3', kids: ['n41'], child: 'n41' },
  n30: { k: 30, x: 755, d: 1, p: 'n17' },
  n26: { k: 26, x: 875, d: 1, mark: true, p: 'n24', kids: ['n35'], child: 'n35' },
  n46: { k: 46, x: 965, d: 1, p: 'n24' },
  n39: { k: 39, x: 390, d: 2, mark: true, p: 'n18' },
  n41: { k: 41, x: 570, d: 2, p: 'n38' },
  n35: { k: 35, x: 875, d: 2, p: 'n26' }
};

var PHASES = ['idle', 'new node', 'splice into root list', 'compare with H.min', 'done'];
var viewMode = 'side by side';
var insertIdx = 0;
var selected = null;
var stepIdx = 0;

/* ---------- small drawing helpers ---------- */
function labelTxt(g, str, x, y, o) {
  o = o || {};
  var t = g.text(String(str));
  t.font({ family: SERIF, size: o.size || 18, anchor: o.anchor || 'middle', weight: o.weight || 'normal' });
  t.fill(o.fill || '#000');
  t.attr({ x: x, y: y, 'dominant-baseline': 'central' });
  if (o.italic) t.attr('font-style', 'italic');
  var ts = t.node.querySelector('tspan');
  if (ts) { ts.setAttribute('x', x); ts.setAttribute('y', y); ts.removeAttribute('dy'); }
  if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': o.halo, 'stroke-linejoin': 'round' });
  return t;
}
function head(g, x, y, ux, uy, color, size) {
  var h = size || 9, hw = h * 0.44, px = -uy, py = ux;
  g.polygon([[x, y], [x - ux * h + px * hw, y - uy * h + py * hw], [x - ux * h - px * hw, y - uy * h - py * hw]]).fill(color);
}
function fharrow(g, x1, y1, x2, y2, o) {
  o = o || {};
  var col = o.color || INK, w = o.width || 1.4, h = o.head || 9;
  var dx = x2 - x1, dy = y2 - y1, L = Math.sqrt(dx * dx + dy * dy);
  if (L < 1) return;
  var ux = dx / L, uy = dy / L;
  var ln = g.line(x1, y1, x2 - ux * h * 0.75, y2 - uy * h * 0.75).stroke({ color: col, width: w });
  if (o.dash) ln.attr('stroke-dasharray', o.dash);
  head(g, x2, y2, ux, uy, col, h);
}
function segBetween(g, x1, y1, x2, y2, o) {
  var dx = x2 - x1, dy = y2 - y1, L = Math.sqrt(dx * dx + dy * dy) || 1;
  var ux = dx / L, uy = dy / L;
  g.line(x1 + ux * R, y1 + uy * R, x2 - ux * R, y2 - uy * R).stroke({ color: o.color || INK, width: o.width || 1.4 });
}
function dirArrow(g, x1, y1, x2, y2, o) {
  o = o || {};
  var off = o.off || 0;
  var dx = x2 - x1, dy = y2 - y1, L = Math.sqrt(dx * dx + dy * dy) || 1;
  var ux = dx / L, uy = dy / L, px = -uy, py = ux;
  fharrow(g, x1 + ux * R + px * off, y1 + uy * R + py * off, x2 - ux * R + px * off, y2 - uy * R + py * off,
    { color: o.color || INK, width: o.width || 1.4, head: 9 });
}

/* ---------- model helpers ---------- */
function isVisible(id) { return id !== 'n21' || insertIdx >= 1; }
function rootList() {
  var r = ['n23', 'n7', 'n3', 'n17', 'n24'];
  if (insertIdx >= 2) r.push('n21');
  return r;
}
function ringsFor() {
  return [
    { list: rootList(), row: 0 },
    { list: ['n18', 'n52', 'n38'], row: 1 },
    { list: ['n30'], row: 1 },
    { list: ['n26', 'n46'], row: 1 },
    { list: ['n39'], row: 2 },
    { list: ['n41'], row: 2 },
    { list: ['n35'], row: 2 }
  ];
}
function ringOf(id) {
  if (id === 'n21' && insertIdx === 1) return ['n21'];
  var rs = ringsFor();
  for (var i = 0; i < rs.length; i++) if (rs[i].list.indexOf(id) >= 0) return rs[i].list;
  return [id];
}
function keyOf(id) { return N[id] ? N[id].k : '—'; }

/* ---------- circular doubly linked list rails ---------- */
function drawRing(g, list, y, accentId) {
  var first = N[list[0]], last = N[list[list.length - 1]];
  var xL = first.x - R - REXT, xR = last.x + R + REXT;
  function col(a, b) { return (accentId && (a === accentId || b === accentId)) ? TEAL : INK; }
  function wid(a, b) { return (accentId && (a === accentId || b === accentId)) ? 2.2 : 1.4; }

  var i, a, b;
  for (i = 0; i < list.length - 1; i++) {
    a = N[list[i]]; b = N[list[i + 1]];
    fharrow(g, a.x + R, y - ROFF, b.x - R, y - ROFF, { color: col(list[i], list[i + 1]), width: wid(list[i], list[i + 1]) });
    fharrow(g, b.x - R, y + ROFF, a.x + R, y + ROFF, { color: col(list[i], list[i + 1]), width: wid(list[i], list[i + 1]) });
  }
  var cw = col(list[list.length - 1], list[0]), ww = wid(list[list.length - 1], list[0]);
  var yT = y - RWRAP, yB = y + RWRAP;

  var pUp = 'M ' + (last.x + R) + ' ' + (y - ROFF) +
    ' H ' + (xR - RRAD) + ' Q ' + xR + ' ' + (y - ROFF) + ' ' + xR + ' ' + (y - ROFF - RRAD) +
    ' V ' + (yT + RRAD) + ' Q ' + xR + ' ' + yT + ' ' + (xR - RRAD) + ' ' + yT +
    ' H ' + (xL + RRAD) + ' Q ' + xL + ' ' + yT + ' ' + xL + ' ' + (yT + RRAD) +
    ' V ' + (y - ROFF - RRAD) + ' Q ' + xL + ' ' + (y - ROFF) + ' ' + (xL + RRAD) + ' ' + (y - ROFF) +
    ' H ' + (first.x - R - 8);
  var eUp = g.path(pUp).fill('none').stroke({ color: cw, width: ww, linejoin: 'round' });
  head(g, first.x - R, y - ROFF, 1, 0, cw, 9);

  var pDn = 'M ' + (first.x - R) + ' ' + (y + ROFF) +
    ' H ' + (xL + RRAD) + ' Q ' + xL + ' ' + (y + ROFF) + ' ' + xL + ' ' + (y + ROFF + RRAD) +
    ' V ' + (yB - RRAD) + ' Q ' + xL + ' ' + yB + ' ' + (xL + RRAD) + ' ' + yB +
    ' H ' + (xR - RRAD) + ' Q ' + xR + ' ' + yB + ' ' + xR + ' ' + (yB - RRAD) +
    ' V ' + (y + ROFF + RRAD) + ' Q ' + xR + ' ' + (y + ROFF) + ' ' + (xR - RRAD) + ' ' + (y + ROFF) +
    ' H ' + (last.x + R + 8);
  var eDn = g.path(pDn).fill('none').stroke({ color: cw, width: ww, linejoin: 'round' });
  head(g, last.x + R, y + ROFF, -1, 0, cw, 9);

  var names = list.map(keyOf).join(' → ');
  [eUp, eDn].forEach(function (el, idx) {
    el.css('cursor', 'pointer');
    el.on('mousemove', function (e) {
      showTooltip((idx === 0 ? 'right (next) pointers: ' : 'left (prev) pointers: ') + names + ' — and back around', e);
    });
    el.on('mouseleave', hideTooltip);
    el.on('click', function () {
      showPopup('A circular doubly linked list',
        'This sibling list [' + names + '] is a ring: every node stores a left and a right pointer, and following either direction always returns to the start. ' +
        'Because the ring has no head or tail, splicing a node in or out costs a constant number of pointer writes.');
    });
  });
}

/* ---------- nodes ---------- */
function nodeDesc(id) {
  var n = N[id];
  var deg = (n.kids || []).length;
  return 'key ' + n.k + ' · ' + (n.mark ? 'marked' : 'unmarked') + ' · degree ' + deg + ' — click for its four pointers';
}
function drawNode(g, id, y) {
  var n = N[id];
  var fill = n.mark ? '#000' : GRAY, stroke = INK, sw = 1.6;
  if (id === 'n21') { fill = TEALFILL; stroke = TEAL; sw = 2.4; }
  g.circle(2 * R).center(n.x, y).fill(fill).stroke({ color: stroke, width: sw });
  labelTxt(g, n.k, n.x, y, { size: 19, fill: n.mark ? '#fff' : '#000', weight: n.mark ? 'bold' : 'normal' });
  var hit = g.circle(2 * R + 6).center(n.x, y).fill('#fff').opacity(0);
  hit.css('cursor', 'pointer');
  hit.on('mousemove', function (e) { showTooltip(nodeDesc(id), e); });
  hit.on('mouseleave', hideTooltip);
  hit.on('click', function () { selectNode(id); });
}
function selectNode(id) {
  selected = (selected === id) ? null : id;
  render();
  if (selected) {
    var n = N[id], ring = ringOf(id), i = ring.indexOf(id), L = ring.length;
    var lft = ring[(i - 1 + L) % L], rgt = ring[(i + 1) % L];
    showPopup('Node ' + n.k + ': four pointers',
      'parent = ' + (n.p ? keyOf(n.p) : 'NIL') + ', child = ' + (n.child ? keyOf(n.child) : 'NIL') +
      ', left = ' + keyOf(lft) + ', right = ' + keyOf(rgt) + '. ' +
      'It also stores degree = ' + ((n.kids || []).length) + ' and mark = ' + (n.mark ? 'TRUE' : 'FALSE') + '. ' +
      'The child pointer names only one arbitrary child; the rest are reached by walking the children\'s ring, which is why a node with a single child points left and right to itself.');
  } else hidePopup();
}

/* ---------- highlight of pointer fields ---------- */
function relArrow(g, x1, y1, x2, y2, text, off) {
  var dx = x2 - x1, dy = y2 - y1, L = Math.sqrt(dx * dx + dy * dy) || 1;
  var ux = dx / L, uy = dy / L, px = -uy, py = ux;
  var sx = x1 + ux * R + px * off, sy = y1 + uy * R + py * off;
  var ex = x2 - ux * R + px * off, ey = y2 - uy * R + py * off;
  fharrow(g, sx, sy, ex, ey, { color: ORANGE, width: 2.2, head: 10 });
  labelTxt(g, text, (sx + ex) / 2 + px * 14, (sy + ey) / 2 + py * 14, { size: 14, fill: ORANGE, halo: 3.2 });
}
function sibArrow(g, x1, y, x2, dy, text, key) {
  var far = Math.abs(x2 - x1) > 260;
  var dir = far ? (text === 'right' ? 1 : -1) : (x2 > x1 ? 1 : -1);
  var xs = x1 + dir * R, xe = far ? x1 + dir * 80 : x2 - dir * R;
  fharrow(g, xs, y + dy, xe, y + dy, { color: ORANGE, width: 2.2, head: 10 });
  labelTxt(g, far ? text + ' = ' + key : text, (xs + xe) / 2, y + dy + (dy < 0 ? -12 : 12),
    { size: 14, fill: ORANGE, halo: 3.2 });
}
function selfLoop(g, x, y) {
  var p = 'M ' + (x - 15) + ' ' + (y - R - 3) + ' A 19 17 0 1 1 ' + (x + 15) + ' ' + (y - R - 3);
  g.path(p).fill('none').stroke({ color: ORANGE, width: 2.2 });
  head(g, x + 15, y - R - 3, 0.72, 0.69, ORANGE, 9);
  labelTxt(g, 'left = right = self', x, y - R - 38, { size: 14, fill: ORANGE, halo: 3.2 });
}
function drawHighlight(g, rows) {
  if (!selected || !isVisible(selected)) return;
  var n = N[selected], y = rows[n.d];
  g.circle(2 * R + 16).center(n.x, y).fill('none').stroke({ color: ORANGE, width: 2.5, dasharray: '5,4' });
  if (n.p) relArrow(g, n.x, y, N[n.p].x, rows[N[n.p].d], 'parent', 11);
  if (n.child) relArrow(g, n.x, y, N[n.child].x, rows[N[n.child].d], 'child', -11);
  var ring = ringOf(selected), i = ring.indexOf(selected), L = ring.length;
  if (L === 1) { selfLoop(g, n.x, y); }
  else {
    sibArrow(g, n.x, y, N[ring[(i + 1) % L]].x, -26, 'right', keyOf(ring[(i + 1) % L]));
    sibArrow(g, n.x, y, N[ring[(i - 1 + L) % L]].x, 26, 'left', keyOf(ring[(i - 1 + L) % L]));
  }
}

/* ---------- insert annotations ---------- */
function badge(g, x, y, text, color) {
  var t = labelTxt(g, text, x, y, { size: 14, fill: color });
  var bb = t.bbox();
  g.rect(bb.width + 16, bb.height + 9).center(x, y).radius(6).fill('#fff').stroke({ color: color, width: 1.2 });
  t.front();
  return { w: bb.width + 16 };
}
function drawInsertAnnot(g, rows, isB) {
  if (insertIdx === 0) return;
  var y0 = rows[0];
  if (insertIdx === 1) {
    badge(g, 1008, y0 + (isB ? 78 : 58), 'new tree · degree 0 · mark = FALSE', TEAL);
  } else if (insertIdx === 2) {
    badge(g, 1008, y0 + (isB ? 78 : 58), 'spliced in: 4 pointer writes', TEAL);
  } else if (insertIdx === 3) {
    var by = isB ? y0 - 72 : y0 - 50;
    var b = badge(g, 770, by, '21 > 3  →  H.min unchanged', TEAL);
    var tip = isB ? y0 - RWRAP - 4 : y0 - R - 5;
    g.line(770 - b.w / 2, by, 490, tip).stroke({ color: TEAL, width: 1.2, dasharray: '4,3' });
    g.line(770 + b.w / 2, by, 1012, tip).stroke({ color: TEAL, width: 1.2, dasharray: '4,3' });
  } else if (insertIdx === 4) {
    badge(g, 1008, y0 + (isB ? 78 : 58), 'insert complete — O(1)', TEAL);
  }
}

/* ---------- panels ---------- */
function drawA(g) {
  var y0 = ROWA[0];
  labelTxt(g, 'H.min', 480, 10, { size: 21, italic: true });
  fharrow(g, 480, 22, 480, y0 - R - 5, { width: 1.7, head: 11 });
  labelTxt(g, '(a)', 42, y0, { size: 23 });

  var roots = rootList(), i;
  for (i = 0; i < roots.length - 1; i++) {
    var a = N[roots[i]], b = N[roots[i + 1]];
    var tl = (roots[i + 1] === 'n21');
    g.line(a.x + R, y0, b.x - R, y0).stroke({ color: tl ? TEAL : INK, width: tl ? 1.8 : 1.4, dasharray: '7,6' });
  }
  Object.keys(N).forEach(function (id) {
    var n = N[id];
    if (!n.p || !isVisible(id)) return;
    var p = N[n.p];
    segBetween(g, p.x, ROWA[p.d], n.x, ROWA[n.d], { color: INK, width: 1.4 });
  });
  Object.keys(N).forEach(function (id) { if (isVisible(id)) drawNode(g, id, ROWA[N[id].d]); });
  drawInsertAnnot(g, ROWA, false);
  drawHighlight(g, ROWA);
}

function drawB(g) {
  var y0 = ROWB[0];
  labelTxt(g, 'H.min', 480, 10, { size: 21, italic: true });
  fharrow(g, 480, 22, 480, y0 - RWRAP - 4, { width: 1.7, head: 11 });
  labelTxt(g, '(b)', 42, y0, { size: 23 });

  var accent = (insertIdx === 2 || insertIdx === 3) ? 'n21' : null;
  ringsFor().forEach(function (rg) { drawRing(g, rg.list, ROWB[rg.row], accent); });
  if (insertIdx === 1) drawRing(g, ['n21'], y0, 'n21');

  Object.keys(N).forEach(function (id) {
    var n = N[id];
    if (!n.p || !isVisible(id)) return;
    var p = N[n.p];
    dirArrow(g, n.x, ROWB[n.d], p.x, ROWB[p.d], { off: 5, color: INK });
    if (p.child === id) dirArrow(g, p.x, ROWB[p.d], n.x, ROWB[n.d], { off: 5, color: INK });
  });
  Object.keys(N).forEach(function (id) { if (isVisible(id)) drawNode(g, id, ROWB[N[id].d]); });
  drawInsertAnnot(g, ROWB, true);
  drawHighlight(g, ROWB);
}

/* ---------- render ---------- */
function render() {
  fhDraw.clear();
  fhDraw.rect(FW, FH).fill('#fff');
  var showA = (viewMode !== '(b) pointer diagram');
  var showB = (viewMode !== '(a) abstract tree view');
  var gA = null, gB = null;
  if (showA && showB) {
    gA = fhDraw.group().attr('transform', 'translate(0,8)');
    gB = fhDraw.group().attr('transform', 'translate(0,292)');
  } else if (showA) {
    gA = fhDraw.group().attr('transform', 'translate(0,262)');
  } else {
    gB = fhDraw.group().attr('transform', 'translate(0,154)');
  }
  if (gA) drawA(gA);
  if (gB) drawB(gB);
  var pl = document.getElementById('phaseLabel');
  if (pl) pl.textContent = 'phase: ' + PHASES[insertIdx];
}

/* ---------- controls ---------- */
function toggle_viewMode(v) { viewMode = v; render(); }

function trigger_insertPhase() {
  insertIdx = (insertIdx + 1) % PHASES.length;
  if (selected === 'n21' && insertIdx === 0) selected = null;
  render();
  var msgs = {
    1: ['Step 1 — make a one-node tree', 'FIB-HEAP-INSERT allocates node 21 with degree 0, mark = FALSE, parent = NIL, child = NIL, and left = right = itself: a circular list of one.'],
    2: ['Step 2 — splice into the root list', 'Four pointer writes are all it takes: 21.left = 24, 21.right = 23, 24.right = 21, 23.left = 21. No roots are compared with each other and no trees are restructured — this is the entire cost of the insert.'],
    3: ['Step 3 — one comparison', 'The only comparison is 21 against H.min.key = 3. Since 21 > 3, H.min stays on node 3. (H.n is incremented too.)'],
    4: ['Done — O(1) amortized', 'The heap now has six trees in its root list. Fibonacci heaps deliberately leave this untidy pile alone; a later EXTRACT-MIN consolidates trees of equal degree and pays for the laziness.'],
    0: ['Reset', 'The heap is back to its original five trees.']
  };
  showPopup(msgs[insertIdx][0], msgs[insertIdx][1]);
}
function trigger_insertReset() { insertIdx = 0; if (selected === 'n21') selected = null; render(); hidePopup(); }

/* ---------- demo player ---------- */
var STEPS = [
  { t: 'The abstract view', v: 'side by side', i: 0, sel: null,
    n: 'Five min-heap-ordered trees hang off a single root list, and H.min points at the smallest root, 3. Black nodes — 18, 39, 26 — are marked: each has already lost one child since it last became a root.' },
  { t: 'The same heap, in pointers', v: '(b) pointer diagram', i: 0, sel: null,
    n: 'Switch to the implementation view: the dashed root line becomes a circular doubly linked list, and each row of siblings gets its own ring. The heap\'s shape never changed — only how much of the bookkeeping we draw.' },
  { t: 'Four pointers per node', v: '(b) pointer diagram', i: 0, sel: 'n18',
    n: 'Node 18 is selected: parent, child, left and right are lit in orange. Click 52, then 30 — single children like 30 point left and right to themselves, a ring of one.' },
  { t: 'Insert: make a lone tree', v: '(b) pointer diagram', i: 1, sel: null,
    n: 'Inserting key 21 creates a brand-new single-node tree with degree 0, mark = FALSE, and left and right pointing to itself.' },
  { t: 'Insert: splice into the root list', v: '(b) pointer diagram', i: 2, sel: null,
    n: 'Four pointer writes (teal) stitch 21 between 24 and 23 in the circular root list. No comparisons among roots, no restructuring — this is the whole of the work.' },
  { t: 'Insert: one comparison', v: '(b) pointer diagram', i: 3, sel: null,
    n: '21 is compared only against H.min\'s key, 3. Since 21 > 3, H.min stays put and the insertion finishes in O(1).' },
  { t: 'Back to the abstract picture', v: '(a) abstract tree view', i: 4, sel: null,
    n: 'Return to view (a): the heap is now six trees in the root list. Lazy insertion leaves the mess for a later EXTRACT-MIN to consolidate.' }
];
function applyStep(k) {
  stepIdx = (k + STEPS.length) % STEPS.length;
  var s = STEPS[stepIdx];
  viewMode = s.v;
  var sel = document.getElementById('viewModeInput');
  if (sel) sel.value = s.v;
  insertIdx = s.i;
  selected = s.sel;
  render();
  document.getElementById('stepTitle').textContent = s.t;
  document.getElementById('demoNarration').textContent = s.n;
  document.getElementById('stepLabel').textContent = 'step ' + (stepIdx + 1) + ' / ' + STEPS.length;
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

applyStep(0);
window.__markRendered();
